export function getUseCaseContent(uc: UseCase): UseCaseContent {
  const override = USE_CASE_CONFIG[uc.slug];
  return {
    heroLead: override?.heroLead ?? `Plan ${uc.name}: ${uc.job}.`,
    heroSub: override?.heroSub ?? 'Define store acceptance criteria before selecting a supplier.',
    scenarios: override?.scenarios ?? [
      { title: 'Entry', body: `Registry trigger example, not a requirement: ${uc.trigger}. Replace thresholds and timing with written store eligibility and expected entry timestamps; replay qualifying and nonqualifying events and compare actual queue entries.` },
      { title: 'Exit', body: `Registry suppression examples to review: ${uc.exclusions.join('; ')}. Require permission withdrawal exits, relevant purchase cancellation and stock checks where an offer depends on availability. Define other suppressions separately; gift buyers/recipients, wholesale and irregular usage need separately owned workflows rather than blanket exclusion. Write cancellation, deferment and re-entry outcomes, then verify queue traces.` },
      { title: 'Measurement', body: `Registry metric examples: ${uc.metrics.join(', ')}. Choose store outcomes, units, numerator, denominator, observation window and cost allocation before rehearsal; define zero denominators as undefined and reconcile an event ledger against expected counts.` },
    ],
    campaignNotes: [
      `Configurable registry trigger example; replace numeric thresholds with store criteria: ${uc.trigger}`,
      `Configurable registry timing example, not a required schedule: ${uc.timing}`,
      `Registry suppression examples, not categorical exclusions: ${uc.exclusions.join('; ')}. Permission withdrawal, relevant purchase exits and offer inventory checks are required; configure other suppressions and separately owned gift buyer/recipient, wholesale and irregular-usage workflows with written queue outcomes.`,
      `Metrics to define and measure: ${uc.metrics.join(', ')}.`,
      `Common mistakes to check: ${uc.mistakes.join('; ')}.`,
    ],
    picks: override?.picks ?? [],
    featuredSlugs: override?.featuredSlugs ?? [],
    toolParagraphs: {},
  };
}
